import{_ as t,o as e,c as n,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Agent 面试 · 可靠性与安全","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/reliability-interview.md","filePath":"guide/agent/reliability-interview.md"}'),r={name:"guide/agent/reliability-interview.md"};function l(s,a,d,h,o,p){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="agent-面试-·-可靠性与安全" tabindex="-1">Agent 面试 · 可靠性与安全 <a class="header-anchor" href="#agent-面试-·-可靠性与安全" aria-label="Permalink to “Agent 面试 · 可靠性与安全”">​</a></h1><blockquote><p>会做 Demo 和能上线的差别，多半在这一页。</p></blockquote><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>Agent 常见失败模式有哪些？怎么兜底？</li><li>如何防止死循环、乱删数据、成本爆炸？</li><li>权限和安全怎么做？</li><li>怎么观测一个 Agent 好不好用？</li><li>幻觉导致错误调工具怎么办？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-失败模式-→-兜底" tabindex="-1">1）失败模式 → 兜底 <a class="header-anchor" href="#_1-失败模式-→-兜底" aria-label="Permalink to “1）失败模式 → 兜底”">​</a></h3><table tabindex="0"><thead><tr><th>失败</th><th>兜底</th></tr></thead><tbody><tr><td>死循环调工具</td><td><strong>最大步数</strong>、全局超时、同工具连续失败熔断</td></tr><tr><td>参数幻觉</td><td>JSON Schema 校验；失败回传「缺字段」让模型改；超次降级人工</td></tr><tr><td>工具超时 / 下游挂</td><td>超时、重试（仅幂等）、熔断、返回可理解错误</td></tr><tr><td>重复执行（支付/下单）</td><td>幂等键、业务去重表</td></tr><tr><td>结果不可验</td><td>结构化输出 + 业务规则 + 抽检</td></tr><tr><td>成本炸</td><td>限流、分模型档位、缓存重复查询</td></tr></tbody></table><p>金句：<strong>没有步数上限和权限的 Agent，不叫产品，叫事故源。</strong></p><h3 id="_1-5-四件事一开始就嵌进项目-开口-40-秒" tabindex="-1">1.5）四件事一开始就嵌进项目（开口 40 秒） <a class="header-anchor" href="#_1-5-四件事一开始就嵌进项目-开口-40-秒" aria-label="Permalink to “1.5）四件事一开始就嵌进项目（开口 40 秒）”">​</a></h3><p>面试官若问「你项目里可靠性怎么做的」，不要只说「我们有重试」。按四句说：</p><table tabindex="0"><thead><tr><th>能力</th><th>口语怎么说</th></tr></thead><tbody><tr><td><strong>超时</strong></td><td>每步 Tool/模型有 deadline，整条流水线有总超时；超时进失败/待重试/待人工，不挂死</td></tr><tr><td><strong>重试</strong></td><td>只重试读和检索；写操作默认不盲目重试</td></tr><tr><td><strong>幂等</strong></td><td>改世界的动作带 key（如 runId+step），重复执行不产生第二封邮件、第二单</td></tr><tr><td><strong>审计</strong></td><td>记谁发起、哪个 Agent、调了啥、摘要、耗时、成败、人审没有——能回放</td></tr></tbody></table><p>多 Agent：<strong>编排管总超时和预算，子步骤管自己的 deadline；写操作的 key 跨 Agent 也要唯一。</strong></p><p>再补一句边界：Checkpoint 管进度，幂等管重复执行安不安全，审计管事后查得出——别混成一句「做了高可用」。</p><h3 id="_2-护栏分层-好画图" tabindex="-1">2）护栏分层（好画图） <a class="header-anchor" href="#_2-护栏分层-好画图" aria-label="Permalink to “2）护栏分层（好画图）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>L1 提示词边界（角色、禁止事项）</span></span>
<span class="line"><span>L2 工具白名单 + Schema</span></span>
<span class="line"><span>L3 权限与租户隔离</span></span>
<span class="line"><span>L4 步数 / 超时 / 预算</span></span>
<span class="line"><span>L5 人工审批（高危写操作）</span></span>
<span class="line"><span>L6 日志审计与回放</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>面试官爱听你说「哪一层拦什么」，而不是只说「我们很谨慎」。</p><h3 id="_3-安全要点" tabindex="-1">3）安全要点 <a class="header-anchor" href="#_3-安全要点" aria-label="Permalink to “3）安全要点”">​</a></h3><ul><li>API Key <strong>永不进前端</strong>；工具凭据最小权限</li><li>提示词注入：不可信用户输入与系统指令隔离；工具结果当数据不当指令</li><li>文件 / Shell 类工具：目录沙箱、命令黑名单</li><li>日志脱敏：手机号、Token、身份证</li></ul><h3 id="_4-观测指标-能量化更好" tabindex="-1">4）观测指标（能量化更好） <a class="header-anchor" href="#_4-观测指标-能量化更好" aria-label="Permalink to “4）观测指标（能量化更好）”">​</a></h3><ul><li>任务成功率 / 人工接管率</li><li>平均步数、平均耗时、平均 Token / 费用</li><li>工具错误率、Schema 校验失败率</li><li>超时与熔断次数</li></ul><p>能说：「我们看成功率、步数和费用；步数突增先查是否死循环或工具描述不清。」</p><h3 id="_5-幻觉调错工具" tabindex="-1">5）幻觉调错工具 <a class="header-anchor" href="#_5-幻觉调错工具" aria-label="Permalink to “5）幻觉调错工具”">​</a></h3><p>流程：校验失败 → 把错误信息作为观察结果喂回 → 允许再试 N 次 → 仍失败则结束并标「需人工」。<br> 不要静默吞掉错误假装成功。</p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「和普通微服务稳定性比？」→ 多了模型不确定性和提示词变量；更依赖契约与护栏。</li><li>「如何回归测试？」→ 固定用例集：黄金对话、工具 mock、断言最终状态与是否调了危险工具。</li></ul>`,28)])])}const g=t(r,[["render",l]]);export{b as __pageData,g as default};
